def fill_slugs(apps, schema_editor):
    """Existing public profiles get a stable URL from their name (/team/<slug>)."""
    from django.utils.text import slugify

    from apps.academy_news.slugs import transliterate

    TeamMember = apps.get_model("website", "TeamMember")
    taken = set()
    for member in TeamMember.objects.select_related("teacher__user").order_by("pk"):
        name = member.name
        if not name and member.teacher_id:
            user = member.teacher.user
            name = f"{user.first_name} {user.last_name}".strip()
        base = slugify(transliterate(name or ""))[:200].strip("-") or f"member-{member.pk}"
        slug, number = base, 2
        while slug in taken:
            slug = f"{base}-{number}"
            number += 1
        taken.add(slug)
        member.slug = slug
        member.save(update_fields=["slug"])


